<?php
require_once __DIR__ . '/../public/db_connect.php';

$station_id = 1; // adjust as needed

foreach (['transaction_adjustment', 'delivery_adjustment'] as $adj_type) {  echo "\n=== $adj_type ===\n";  $sp = $pdo->prepare("SELECT COUNT(*) FROM fuel_adjustments WHERE station_id = ? AND adjustment_type = ?");  $sp->execute([$station_id, $adj_type]);  echo "Total: " . $sp->fetchColumn() . "\n";  $sp2 = $pdo->prepare("SELECT COUNT(*) FROM fuel_adjustments WHERE station_id = ? AND adjustment_type = ? AND DATE(adjustment_date) = CURDATE()");  $sp2->execute([$station_id, $adj_type]);  echo "Today: " . $sp2->fetchColumn() . "\n";  $sp3 = $pdo->prepare("SELECT COUNT(*) FROM fuel_adjustments WHERE station_id = ? AND adjustment_type = ? AND MONTH(adjustment_date) = MONTH(CURDATE()) AND YEAR(adjustment_date) = YEAR(CURDATE())");  $sp3->execute([$station_id, $adj_type]);  echo "This Month: " . $sp3->fetchColumn() . "\n";  $sp4 = $pdo->prepare("SELECT created_at FROM fuel_adjustments WHERE station_id = ? AND adjustment_type = ? ORDER BY id DESC LIMIT 1");  $sp4->execute([$station_id, $adj_type]);  $last = $sp4->fetchColumn();  echo "Last: " . ($last ?: '—') . "\n";  // Main list query  $sql = "SELECT fa.*,  COALESCE(  NULLIF(CONCAT(TRIM(COALESCE(u.first_name, '')), ' ', TRIM(COALESCE(u.last_name, ''))), ' '),  u.username, 'Unknown'  ) as manager_name  FROM fuel_adjustments fa  LEFT JOIN users u ON fa.user_id = u.id  WHERE fa.station_id = ? AND fa.adjustment_type = ?  AND DATE(fa.adjustment_date) BETWEEN ? AND ?  ORDER BY fa.adjustment_date DESC, fa.created_at DESC";  $stmt = $pdo->prepare($sql);  $stmt->execute([$station_id, $adj_type, date('Y-m-d', strtotime('-30 days')), date('Y-m-d')]);  $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo "Rows in last 30 days: " . count($rows) . "\n";  foreach ($rows as $r) {  $nd = json_decode($r['notes'], true) ?: [];  echo "  ADJ-{$r['id']} | {$r['fuel_type']} | Prev:{$r['previous_value']} -> New:{$r['new_value']} | By:{$r['manager_name']}\n";  echo "  Notes keys: " . implode(', ', array_keys($nd)) . "\n";  }
}
echo "\nDone.\n";
